import pandas as pd

def main():
    # Source file paths
    source_files = [
        "autopipeline-benchmarks/github-pipelines/length1_91/test_0.csv"
    ]

    dfs = []
    for file in source_files:
        # Load CSV ignoring the first index column
        df = pd.read_csv(file, index_col=0)

        # Trim whitespace and convert string columns
        str_cols = ['Name', 'Position', 'Team_from', 'League_from', 'Team_to', 'League_to', 'Season']
        for col in str_cols:
            if col in df.columns:
                df[col] = df[col].astype(str).str.strip()
            else:
                df[col] = ""

        # Convert Age to integer safely
        if 'Age' in df.columns:
            df['Age'] = pd.to_numeric(df['Age'], errors='coerce').fillna(0).astype(int)
        else:
            df['Age'] = 0

        # Convert Market_value to float (NaNs allowed)
        if 'Market_value' in df.columns:
            df['Market_value'] = pd.to_numeric(df['Market_value'], errors='coerce')
        else:
            df['Market_value'] = float('nan')

        # Convert Transfer_fee to integer safely
        if 'Transfer_fee' in df.columns:
            df['Transfer_fee'] = pd.to_numeric(df['Transfer_fee'], errors='coerce').fillna(0).astype(int)
        else:
            df['Transfer_fee'] = 0

        # Keep only target columns in correct order
        target_columns = ['Name', 'Position', 'Age', 'Team_from', 'League_from',
                          'Team_to', 'League_to', 'Season', 'Market_value', 'Transfer_fee']
        df = df[target_columns]

        dfs.append(df)

    # Union all source tables (only one here)
    combined_df = pd.concat(dfs, ignore_index=True)

    # Save to target path
    combined_df.to_csv("autopipeline-benchmarks/github-pipelines/length1_91/target_multisource_critique_history.csv", index=False)

if __name__ == "__main__":
    main()
